style.css:
@-moz-document domain("google.com") {
body {
    background-image: url("https://www.rockstargames.com/VI/_next/image?url=%2FVI%2F_next%2Fstatic%2Fmedia%2FLeonida_Keys_01.1af17390.jpg&w=1366&q=75") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-attachment: fixed !important;
  }

  /* Transparentar fondo general */
  #main,
  .L3eUgb {
    background: transparent !important;
  }

  /* Ocultar elementos molestos */
  #hplogo,
  .gb_qa,
  .gb_qe,
  .gb_Kd,
  .gb_fd,
  .gb_g,
  .gb_f,
  .gb_D,
  .gb_W,
  .gb_Zd,
  .gb_Jd {
    display: none !important;
  }

  /* Estilo del buscador */
  .RNNXgb {
    background: rgba(0, 0, 0, 0.3) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(3px) !important;
  }

  input {
    background: rgba(255, 255, 255, 0.2) !important;
    color: white !important;
    border: none !important;
  }

  /* Forzar transparencia del pie de página */
  #fbar,
  #fbar .fbar,
  #fbar .fbar p,
  #fbar .fbar a,
  footer,
  #footer {
    background: rgba(0, 0, 0, 0.3) !important;
    color: white !important;
    backdrop-filter: blur(4px) !important;
    border-top: 1px solid rgba(255, 255, 255, 0.1) !important;
  }

  #fbar a,
  #footer a {
    color: #ffffffcc !important;
  }
}
